// agent-roster.mjs — reads the real agent-type roster (core/agents/ +
// domains/<name>/agents/ + legacy agents/) and a task-spec's own header
// fields, for docs/history/core-foundation-domain-boundary/DISCUSSION.md's D20/D22
// eligibility-inversion resolution (resolveAgentTypeForTaskSpec, src/runner/dispatch/cli.mjs). LAYER: infra
// (same tier as dispatch/cli.mjs, which is the runtime consumer this
// module exists for) -- one-directional-layer forbids dispatch/cli.mjs
// (infra) importing src/setup/registrations.mjs (use-case, shallower). Both
// read an agent file through `readAgentDefinition` (agent-definitions.mjs),
// so the name and skills of an agent have one reader.

import fs from 'node:fs';
import path from 'node:path';

import { readAgentDefinition } from './agent-definitions.mjs';

/**
 * Every real agent-type's `{name, skills}` across `core/agents/`,
 * `domains/<name>/agents/`, and the legacy `agents/` (D24/D33 precedence:
 * core, then domains in sorted order, then legacy last, first occurrence
 * of a name wins -- same order `registrations.mjs`'s own
 * `allAgentYamlFiles` uses). Sorted directory scans throughout (D32,
 * review finding M2) so the roster is identical on every machine/run.
 * Never throws on a malformed individual file: a file that is unreadable or
 * not valid YAML is left out of the roster and named in `problems`
 * (`<file>: cannot be parsed: <reason> (line L, column C)`), so the caller
 * can surface it instead of losing the agent silently.
 *
 * @returns {{ defs: Array<{ name: string, skills: string[] }>, problems: string[] }}
 */
export function loadAgentRoster(cwd) {
  const files = [];
  const seen = new Set();

  const scanDir = (dir) => {
    if (!fs.existsSync(dir)) return;
    for (const name of fs.readdirSync(dir).sort((a, b) => a.localeCompare(b))) {
      if (!name.endsWith('.yaml') && !name.endsWith('.yml')) continue;
      const filePath = path.join(dir, name);
      if (seen.has(filePath)) continue;
      seen.add(filePath);
      files.push(filePath);
    }
  };

  scanDir(path.join(cwd, 'core', 'agents'));
  const domainsDir = path.join(cwd, 'domains');
  if (fs.existsSync(domainsDir)) {
    for (const entry of fs.readdirSync(domainsDir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      if (entry.isDirectory()) scanDir(path.join(domainsDir, entry.name, 'agents'));
    }
  }
  scanDir(path.join(cwd, 'agents'));

  const defs = [];
  const problems = [];
  const namesSeen = new Set();
  for (const filePath of files) {
    const rel = path.relative(cwd, filePath).split(path.sep).join('/');
    let text;
    try {
      text = fs.readFileSync(filePath, 'utf8');
    } catch (error) {
      problems.push(`${rel}: cannot be read (${error.message})`);
      continue;
    }
    const { error, name: declared, skills } = readAgentDefinition(text, { filename: rel });
    if (error) {
      problems.push(`${rel}: ${error}`);
      continue;
    }
    const name = declared ?? path.basename(filePath).replace(/\.ya?ml$/, '');
    if (namesSeen.has(name)) continue; // first occurrence wins, D33's own precedence
    namesSeen.add(name);
    defs.push({ name, skills });
  }
  return { defs, problems };
}

/**
 * A task-spec markdown file's own header fields (the same `key: value |
 * key: value` line `registrations.mjs`'s `parseTaskSpecHeaderFields`
 * already parses for the doctor check) -- only `agent`/`requires-skill`
 * matter to `resolveAgentTypeForTaskSpec`, always normalized to arrays.
 * Returns `{}` (never throws) when the file is missing, unreadable, or
 * has no `domain:`-led header line -- "no header content" is a legitimate
 * "nothing to resolve from" input, not an error.
 */
export function readTaskSpecHeader(filePath) {
  let text;
  try {
    text = fs.readFileSync(filePath, 'utf8');
  } catch {
    return {};
  }
  const headerLine = text.split('\n').find((l) => l.startsWith('domain:'));
  if (!headerLine) return {};
  const res = {};
  for (const part of headerLine.split('|').map((p) => p.trim())) {
    const colonIdx = part.indexOf(':');
    if (colonIdx === -1) continue;
    const key = part.slice(0, colonIdx).trim();
    const valStr = part.slice(colonIdx + 1).trim();
    if (key === 'requires-skill' || key === 'agent') {
      if (valStr.startsWith('[') && valStr.endsWith(']')) {
        res[key] = valStr.slice(1, -1).split(',').map((s) => s.trim()).filter(Boolean);
      } else if (valStr.includes(',')) {
        res[key] = valStr.split(',').map((s) => s.trim()).filter(Boolean);
      } else if (valStr) {
        res[key] = [valStr];
      } else {
        res[key] = [];
      }
    } else {
      res[key] = valStr;
    }
  }
  return res;
}

// anti-loop.mjs — the runner's anti-loop guard (per D2, agent's-discretion
// note in CONTEXT.md on counter placement): a visit counter derived from the
// event log, plus an in-memory circuit breaker for consecutive goal-check
// misses.
//
// PURE: no fs import, no child_process import. `visitCount` takes an already
// -read array of events (as returned by `readEvents`/`foldEvents` upstream)
// — it never opens `.fgos/events.jsonl` itself. `createMissBreaker`'s state
// lives only in the closure returned to the caller; nothing here touches
// disk or a process.
//
// EXECUTING-PHASE ONLY (claim-lock, code review finding, superseded by
// tsk-40m D3): before claim-lock, an item could never reach `doing` before
// stage `executing` (pick/take were frontier-only), so counting every
// `to: 'doing'` move was equivalent to counting only real dispatch
// attempts. Claim-lock let `pick` claim an item at `clarify`/`decompose`
// too — a claim-then-release cycle there is not a dispatch attempt and
// must not eat into the SAME budget real executing retries draw from. That
// scoping used to be reconstructed here by replaying domain+stage per id
// alongside each `to: 'doing'` move (mirroring frontier.mjs's own
// executing check). tsk-40m D3 (docs/history/runtime-claim-doing-
// separation/CONTEXT.md, locked decision — hard migration, no dual-count
// legacy) retired that reconstruction entirely: `countableDoingMoveIndexes`
// below now counts `work.attempt(phase:'execute')` events directly —
// settleClaim (store.mjs) only ever stamps `phase:'execute'` for a real
// dispatch attempt, so the same scoping is now a fact already recorded at
// write time, never inferred at read time.

/** Default max times a single item may be re-dispatched (re-enter `doing`)
 * before the runner refuses to pick it up again. Provisional — tuning is
 * deferred to real operation, per the cell's own note. */
export const MAX_VISITS = 3;

/**
 * Replay just enough of `events` to know, for each `work.move` event with
 * `payload.to === 'doing'` and `payload.id === id`, whether the item's stage
 * at that exact point in the log already equalled its domain's Execute-mapped
 * stage — i.e. whether it was a real executing-phase dispatch, not a
 * clarify/decompose-phase claim (claim-lock). Returns the Set of matching
 * event indexes (positions in `events`), so both `visitCount` and
 * `visitsSinceLastHumanEvent` below can share one scan.
 *
 * Tracks only `domain` (from this id's one `work.add`) and `stage` (from its
 * `work.add` and any later `work.stage` moves) — the two fields
 * frontier.mjs's own eligibility check reads, nothing else. A missing stage
 * reads as the domain's Execute stage (D8 lazy default), same as
 * frontier.mjs and step-fsm.mjs.
 */
function countableDoingMoveIndexes(events, id) {
  const indexes = new Set();
  for (let i = 0; i < events.length; i += 1) {
    const event = events[i];
    if (!event || !event.payload) continue;
    // tsk-40m D3 (docs/history/runtime-claim-doing-separation/CONTEXT.md,
    // locked decision — "anti-loop chuyen sang dem durable work.attempt
    // event (phase:execute) THAY VI work.move->doing... Hard migration --
    // khong giu dual-count legacy"): counts work.attempt(phase:'execute')
    // ONLY, full replacement of the old work.move->doing count, no legacy
    // fallback for a pre-migration item's OWN old doing-moves either — a
    // hard cut, not an additive/dual-count transition. `domain`/`stage`
    // tracking (needed only to scope the OLD work.move->doing fallback to
    // the Execute stage) is retired along with it; work.attempt's own
    // `phase:'execute'` field already carries that same scoping directly,
    // set by settleClaim only for a real dispatch attempt.
    if (event.type === 'work.attempt' && event.payload.id === id && event.payload.phase === 'execute') {
      indexes.add(i);
    }
  }
  return indexes;
}

/** Default number of consecutive goal-check misses (for one item) before
 * the circuit breaker trips. Provisional, same caveat as MAX_VISITS. Inert
 * under shipped defaults: dispatchClaimedItem (loop.mjs) parks an item
 * after at most DEFAULT_MAX_RETRIES (2) retries, so a single item's own
 * streak never reaches this threshold on its own. The breaker only trips
 * when a caller passes an explicit lower `breakerThreshold` to
 * `createMissBreaker` (see its doc comment below) — that path already
 * exists today. */
export const BREAKER_MISSES = 3;

/**
 * Count how many times work item `id` has entered `doing` at its executing
 * stage across `events` (claim-lock: a clarify/decompose-phase claim is not
 * a dispatch attempt — see `countableDoingMoveIndexes` above).
 *
 * Derived from the log's existing `work.move` shape (per key_links: no new
 * event type) — a visit is any event with `type === 'work.move'` and
 * `payload.to === 'doing'` for this id, at that point already at the
 * domain's Execute-mapped stage. Lifetime, agent-agnostic count: a
 * human's manual re-dispatch counts exactly like the runner's. This is the
 * shipped metric (loop.mjs's `visits`/`priorVisits` payload fields, fgos.mjs's
 * `priorVisits`) — untouched by human-rounds D1, which reset the runner's own
 * anti-loop GATE only (see `visitsSinceLastHumanEvent` below), never this
 * lifetime tally.
 *
 * SUPERSEDES the comment this replaced ("there is no privileged writer whose
 * visits don't count"): that was true only because `role` did not exist yet
 * when it was written. `role` is now stamped on every `work.move` event
 * (store.mjs), and human-rounds D1 gives a human's role-attributed events
 * gate-resetting weight the runner's own never gets — this function still
 * treats every writer identically because it is the lifetime metric, not the
 * gate; the gate's asymmetry lives entirely in `visitsSinceLastHumanEvent`.
 */
export function visitCount(events, id) {
  if (!Array.isArray(events) || typeof id !== 'string' || !id) return 0;
  return countableDoingMoveIndexes(events, id).size;
}

/**
 * Count how many times work item `id` has re-entered `doing` SINCE its own
 * last human-attributed event (human-rounds D1) — the anti-loop GATE's own
 * budget, distinct from `visitCount`'s lifetime tally above.
 *
 * Per-item (D1b): only events carrying this exact `id` mark or count.
 *
 * Trigger-set is CLOSED (D1c) and keyed on `role === 'human'` plus payload
 * shape — never on a `from` field:
 *   - `payload.answer !== undefined` — the item left `awaiting-human` via a
 *     human's answer (`answerAwaiting`, status-fsm.mjs's `awaiting-human -> todo`
 *     edge; the only edge `answer` appears on).
 *   - `payload.reason !== undefined` — a human's reject/park-with-reason
 *     (status-fsm.mjs's `awaiting-approval -> todo`/`awaiting-approval -> blocked` edges; the runner's
 *     own reason-carrying parks, e.g. `anti-loop-max-visits`/`breaker-tripped`,
 *     stamp `role: 'runner'`, and `return`/`approve`'s own internal park edges
 *     stamp `role: 'system'` (D30) — neither ever matches here).
 * A bare resume (`blocked -> todo` with no reason) and a human `take`
 * (`blocked -> doing`, `role: 'human'`, no answer/reason) are deliberately
 * NOT triggers — per D1c only the two closed shapes above reset the budget.
 *
 * No qualifying event found for this id → the budget is the item's whole
 * history, i.e. identical to `visitCount(events, id)` (a pure machine loop
 * still dies at the cap — no human event has ever intervened).
 */
export function visitsSinceLastHumanEvent(events, id) {
  if (!Array.isArray(events) || typeof id !== 'string' || !id) return 0;
  let lastHumanIndex = -1;
  for (let i = 0; i < events.length; i += 1) {
    const event = events[i];
    if (
      event &&
      event.type === 'work.move' &&
      event.payload &&
      event.payload.id === id &&
      event.payload.role === 'human' &&
      (event.payload.answer !== undefined || event.payload.reason !== undefined)
    ) {
      lastHumanIndex = i;
    }
  }
  const countable = countableDoingMoveIndexes(events, id);
  let count = 0;
  for (const index of countable) {
    if (index > lastHumanIndex) count += 1;
  }
  return count;
}

/**
 * Has `count` (as returned by `visitCount`) reached or passed the max-visits
 * threshold? At-threshold and past-threshold both block re-dispatch — only
 * strictly-below is still allowed to run again.
 */
export function hasExceededMaxVisits(count, max = MAX_VISITS) {
  return count >= max;
}

/**
 * Sentinel key `createMissBreaker`'s returned methods key on when the caller
 * passes no item id — this is what keeps the backward-compatible
 * `consecutiveMisses` getter and zero-arg `recordMiss()`/`recordHit()`/
 * `isTripped()` calls (loop.mjs's current call sites) working unchanged. A
 * `Symbol` rather than a string so it can never collide with a real item id.
 */
const DEFAULT_ITEM_KEY = Symbol('anti-loop.default-item');

/**
 * Create a fresh consecutive-miss circuit breaker.
 *
 * **Per-item (fan-out-parallel D15):** under Epic 3's batch dispatch,
 * multiple different items run concurrently, so one counter shared across
 * an entire runner run would wrongly conflate item A's goal-check miss with
 * item B's, tripping the breaker on unrelated failures across different
 * items. The breaker is keyed by item id (`Map<id, consecutiveCount>`): an
 * id never explicitly seen before starts at 0/untripped, and two different
 * ids never share or influence each other's streak. `recordMiss(itemId)`
 * increments that item's own streak, `recordHit(itemId)` resets it to 0,
 * and `isTripped(itemId)` reports that item's own trip state at `threshold`.
 *
 * The item id argument is optional and defaults to an internal sentinel key
 * (see `DEFAULT_ITEM_KEY`) — this keeps loop.mjs's existing zero-arg calls
 * (`breaker.recordMiss()`, etc., still one-item-at-a-time as of this cell)
 * behaved exactly as before per-item keying was introduced. The
 * `consecutiveMisses` property stays a plain getter (a getter cannot take
 * an argument) and reads the same sentinel key; `consecutiveMissesFor(id)`
 * is the new method for reading any specific item's streak.
 *
 * Per the reliability-panel revision (D2 note "d"): this counter is
 * deliberately NOT event-derived. It is in-memory state scoped to one
 * runner run (matches A1's sequential-once-per-run shape, e.g. a `--once`
 * invocation) — cross-run persistence of consecutive-miss state is out of
 * scope for Phase 2. UPDATED (str7-str8-priority-intent D7/D8/D9): under
 * `--watch`'s `runWatch` (loop.mjs), "one runner run" means the WHOLE watch
 * session, not one cycle — `runWatch` creates a single breaker before its
 * loop starts and threads the SAME object into every `runOnce` cycle via
 * `options.breaker`, so this state deliberately persists and accumulates
 * ACROSS cycles for as long as the watch process runs. This is intentional:
 * a persistent daemon should accumulate failure history toward a trip,
 * unlike a single bounded `--once` pass. Cross-PROCESS persistence (surviving
 * a restart) is still out of scope.
 *
 * Because this state exists only in the closure below, replaying or reading
 * the event log never affects it — an unrelated event (e.g. a human writing
 * a `decision`, or another item's `work.move`) that the caller does not
 * report through `recordMiss()`/`recordHit()` leaves the streak untouched.
 *
 * **Reachable under `--watch` (str7-str8-priority-intent D9), NOT inert
 * (supersedes phase2-p1-breaker-inert-fix's "dead under shipped defaults"
 * claim for that mode):** with `threshold` at its default (`BREAKER_MISSES`
 * = 3), a single `--once` invocation still can never trip the breaker from
 * one item's own retries alone — `dispatchClaimedItem` (loop.mjs) parks an
 * item after at most `DEFAULT_MAX_RETRIES` (2) failed attempts, one short of
 * tripping, so within ONE `--once` pass the halt branch this feeds
 * (`loop.mjs`'s `if (tripped)`) stays dead under default configuration, not
 * broken. But under `--watch`, the breaker is shared across every cycle of
 * the whole watch session (see the UPDATED note above), so an item that gets
 * re-dispatched and re-misses across multiple SEPARATE cycles (each cycle
 * itself capped at `DEFAULT_MAX_RETRIES`, but the streak no longer resets
 * between cycles) CAN reach the default threshold and trip — the "inert
 * under shipped defaults" claim no longer holds once `--watch` is in use. A
 * caller can still pass an explicit lower `threshold` (e.g.
 * `breakerThreshold: 1`) to reach the branch sooner in either mode.
 */
export function createMissBreaker(threshold = BREAKER_MISSES) {
  const streaks = new Map();
  return {
    recordMiss(itemId = DEFAULT_ITEM_KEY) {
      const next = (streaks.get(itemId) || 0) + 1;
      streaks.set(itemId, next);
      return next;
    },
    recordHit(itemId = DEFAULT_ITEM_KEY) {
      streaks.set(itemId, 0);
      return 0;
    },
    isTripped(itemId = DEFAULT_ITEM_KEY) {
      return (streaks.get(itemId) || 0) >= threshold;
    },
    consecutiveMissesFor(itemId) {
      return streaks.get(itemId) || 0;
    },
    get consecutiveMisses() {
      return streaks.get(DEFAULT_ITEM_KEY) || 0;
    },
  };
}

// D1/D4 (docs/history/session-claim-liveness/CONTEXT.md): the "is this
// claim's worktree still being actively touched" signal -- real file/commit
// activity, never session/process identity or claim-age. Reused by
// claim-port.mjs's stale-claim reclaim pre-check (D2/D5).

import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { branchNameFor, findCheckoutPath } from './worktree.mjs';
import { STALE_DOING_DEFAULTS } from '../state/graph-metrics.mjs';
import { statusPaths, GIT_LIST_MAX_BUFFER } from '../util/git-paths.mjs';

function git(repoRoot, args) {
  return execFileSync('git', args, { cwd: repoRoot, encoding: 'utf8', shell: false });
}

/**
 * D4: `max(last commit time on the claim's fgw/<id> branch, newest mtime
 * among the files `git status --porcelain` lists in its current worktree)`,
 * epoch ms -- or `null` when the signal is unreadable (branch doesn't
 * exist, no live worktree registered for it, or a git call fails).
 *
 * `null` is deliberately never coerced to 0/Infinity: a caller must treat
 * it as inconclusive (D5), the same as a genuinely recent timestamp --
 * never as "ancient enough to reclaim" by accident.
 *
 * The `:!.fgos` status exclusion mirrors `isCheckoutDirty`
 * (`worktree.mjs`) -- ADR0020's own `.fgos` removal on checkout must never
 * look like real activity.
 */
export function lastActivityAt(repoRoot, id) {
  const branch = branchNameFor(id);

  let commitTs;
  try {
    const raw = git(repoRoot, ['log', '-1', '--format=%ct', branch]).trim();
    const seconds = Number.parseInt(raw, 10);
    if (Number.isFinite(seconds)) commitTs = seconds * 1000;
  } catch {
    return null; // branch doesn't exist -- nothing to measure at all
  }

  let porcelainWorktrees;
  try {
    porcelainWorktrees = git(repoRoot, ['worktree', 'list', '--porcelain']);
  } catch {
    return commitTs ?? null;
  }

  const worktreePath = findCheckoutPath(porcelainWorktrees, branch);
  if (!worktreePath) return commitTs ?? null; // branch exists, no live checkout -- commit time is all there is

  let statusOutput;
  try {
    // tsk-f8f: `-z` (NUL-terminated records), not the human-readable
    // newline format -- `git status --porcelain` (no `-z`) C-style-quotes
    // any path containing whitespace or other "unusual" characters (`??
    // "my file.txt"`), which the old `trimmed.split(/\s+/).pop()` parse
    // took literally, yielding a fragment like `file.txt"` (a lone
    // trailing quote character) that never matches a real file --
    // `statSync` fails, the entry is silently skipped, and that file's
    // mtime never contributes to the activity signal. `-z` mode never
    // quotes paths at all (verified empirically: a path with spaces comes
    // through raw, byte-for-byte), so there is no escape/quote format to
    // parse in the first place.
    statusOutput = execFileSync('git', ['-C', worktreePath, 'status', '--porcelain=v1', '-z', '--untracked-files=all', '--', ':!.fgos'], {
      cwd: repoRoot, encoding: 'utf8', shell: false, maxBuffer: GIT_LIST_MAX_BUFFER,
    });
  } catch {
    return commitTs ?? null;
  }

  let newestMtime;
  // Parsed by `statusPaths`: a rename or copy gives both halves, and the
  // source half no longer exists, so its statSync fails and is skipped.
  for (const filePath of statusPaths(statusOutput)) {
    try {
      const mtime = fs.statSync(path.join(worktreePath, filePath)).mtimeMs;
      if (newestMtime === undefined || mtime > newestMtime) newestMtime = mtime;
    } catch {
      // Listed by status but unreadable/deleted between the two calls --
      // skip it rather than aborting the whole signal over one entry.
    }
  }

  const candidates = [commitTs, newestMtime].filter((value) => value !== undefined);
  return candidates.length > 0 ? Math.max(...candidates) : null;
}

/**
 * D2/D3: is the claim on `id` conclusively quiet as of `now`? `claimRole`
 * selects the threshold bucket the same way `classifyStaleDoing`
 * (`graph-metrics.mjs`) already does for its own advisory -- `runner` gets
 * the short `agentMs` grace, everything else gets the long `humanMs` grace.
 * D3 reuses `STALE_DOING_DEFAULTS` as-is rather than a separate, more
 * conservative pair.
 *
 * An unreadable signal (`lastActivityAt` returns `null`) is never
 * conclusive -- this returns `false`, the same outcome as genuinely recent
 * activity, so the caller's fallback (refuse exactly as today) covers both.
 */
export function isReclaimEligible(repoRoot, id, claimRole, { now = Date.now(), thresholds = STALE_DOING_DEFAULTS } = {}) {
  const activityAt = lastActivityAt(repoRoot, id);
  if (activityAt === null) return false;
  const thresholdMs = claimRole === 'runner' ? thresholds.agentMs : thresholds.humanMs;
  return now - activityAt > thresholdMs;
}

// claim-port.mjs — single choke-point for all claim flows (tsk-53f D1).
//
// Every claim (CLI take, CLI pick, runner claimItem) goes through this module.
// Centralizes: main checkout mutex around the .fgos checkpoint only
// (repo-locks.mjs), the worker-slot ceiling check + acquireClaim in one state
// transaction (runtime claim only — tsk-40m retired the durable
// moveWork(to:'doing') claim-time write entirely; doing is derived purely from
// the active-claim overlay), optional worktree creation with correct baseRef for leaf items.
//
// This is the "one door" for claiming work — no direct acquireClaim call
// outside this module except for FSM-internal transitions.

import { moveWork, addOutcome, addDecision, recordClaimAttempt, readRawEvents, FsmError } from '../state/store.mjs';
import { foldEvents } from '../state/replay.mjs';
import { isResolvedStatus, resolveRoot } from '../state/frontier.mjs';
import { getDomain, stepForPhase, effectiveStep } from '../state/domain-registry.mjs';
import { visitCount } from './anti-loop.mjs';
import { withMainCheckout } from './repo-locks.mjs';
import { checkpointMainFgos } from './main-fgos-checkpoint.mjs';
import { LockScope, HolderLockError } from '../holder-lock/index.mjs';
import { createClaimWorktree, branchNameFor, branchExists, currentHead, resolveRefSha } from './worktree.mjs';
import { lastActivityAt, isReclaimEligible } from './claim-liveness.mjs';
import { hasWorkerSlotRoom } from '../state/worker-slots.mjs';
import { readSharedConfigOrEmpty } from '../config/shared-config-file.mjs';
import { acquireClaimTx, releaseClaim, readClaims, readClaim, buildEffectiveView, getItemDurableRevision, withMainState } from '../state/runtime-coordination.mjs';
import path from 'node:path';

import { DEFAULTS } from '../state/work.mjs';

/**
 * Read `releaseTrigger` off the MOST RECENT settle-to-'todo' event for
 * `id` — a `work.move(to: 'todo')`, or (tsk-40m: a same-state settle whose
 * preClaimStatus was already 'todo' writes no work.move at all) a
 * `work.attempt(to: 'todo')` — never off a durable item field, so a later
 * reject/verify-fail-park (which never carries this marker) always wins
 * over an earlier claim-lock §3b release's marker instead of the stale
 * value silently surviving (tsk-2zv). Returns `undefined` when the item
 * has never settled to `todo`, or when its latest such settle didn't carry
 * the marker (reject, verify-fail park, or a genuinely fresh take).
 */
function latestTodoReleaseTrigger(events, id) {
  let marker;
  for (const event of events) {
    if (!event || !event.payload) continue;
    if (event.payload.id !== id || event.payload.to !== 'todo') continue;
    if (event.type === 'work.move' || event.type === 'work.attempt') {
      marker = event.payload.releaseTrigger;
    }
  }
  return marker;
}

// category (R4, store.mjs's categoryOf contract): 'not-found' mirrors
// StoreError's own not-found convention ('validation'); 'lock-held'
// reuses 'lock-timeout' (events.mjs's own category for the
// same "couldn't get exclusive access" class) — without this, an uncategorized
// ClaimError falls through categoryOf to 'unexpected' and crashes the whole
// runOnce drain-run instead of a graceful per-item halt (same failure mode
// store.mjs's own EXIT_CODES comment documents for WorktreeError/MergeError).
const CLAIM_ERROR_CATEGORY = Object.freeze({
  'not-found': 'validation',
  'lock-held': 'lock-timeout',
  'deps-not-merged': 'validation',
  // Same reasoning as 'deps-not-merged': a refused claim is an ordinary,
  // expected outcome, so the runner must halt this one item gracefully
  // rather than crash its whole drain-run on an 'unexpected' category.
  'worker-slot-ceiling': 'validation',
  // The pre-claim durable-status CAS below (tsk-40m D2: preClaimStatus vs
  // expectedStatus) reports the same 'conflict' category moveWork's own CAS
  // always has for "the state changed since you read it" — a real,
  // expected concurrent-claim outcome (exit 3), not a crash.
  conflict: 'conflict',
});

export class ClaimError extends Error {
  constructor(code, message, details = {}) {
    super(message);
    this.name = 'ClaimError';
    this.code = code;
    this.category = CLAIM_ERROR_CATEGORY[code] ?? 'unexpected';
    Object.assign(this, details);
  }
}

/**
 * Claim work through the single choke-point.
 *
 * @param {string} dir - .fgos directory
 * @param {Object} opts
 * @param {string} opts.id - work item id
 * @param {string} opts.actor - 'session' | 'runner' | 'human'
 * @param {boolean} opts.isolate - if true, create worktree (pick behavior); if false, no worktree (take behavior)
 * @param {string} [opts.claimTrigger] - optional claim trigger stamp
 * @param {string} [opts.repoRoot] - repo root (defaults to process.cwd())
 * @param {string} [opts.worktreeDir] - custom worktree directory (for runner)
 * @returns {Object} claim result with worktree info if isolated
 */
export async function claimWork(dir, { id, actor, isolate, claimTrigger, repoRoot = process.cwd(), worktreeDir, skipOutcome = false, waitMs } = {}) {
  // Everything that needs a child process happens before the state lock: the
  // checkout's HEAD is read once, here, and that one answer is both the commit
  // a fresh worktree forks from and the commit recorded on the claim.
  const head = currentHead(repoRoot);
  const scope = new LockScope('claim');

  // The main checkout mutex (rank 50) is held only for the `.fgos` checkpoint.
  // The ceiling check below no longer leans on it: it runs inside the `state`
  // transaction, so two claims for the last slot still cannot both pass.
  try {
    await withMainCheckout(scope, 'claim', (mainHandle) => checkpointMainFgos(mainHandle, dir, repoRoot), { fgosDir: dir, waitMs });
  } catch (err) {
    if (err instanceof HolderLockError && err.code === 'lock-held') {
      throw new ClaimError('lock-held', `claimWork: ${err.message}`, { holders: err.holders, lock: err.lock, timedOut: err.timedOut });
    }
    throw err;
  }

  // Tầng A (T2/T3): events now live under baseline-0 (.fgos/events.jsonl)
  // PLUS every per-writer file under .fgos/events/ -- readRawEvents(dir)
  // is the one door that reads all of it, merged/deduped (TA-D7/TA-D13).
  const rawEvents = readRawEvents(dir);
  const durableView = foldEvents(rawEvents);
  const claims = readClaims(dir);
  const view = buildEffectiveView(durableView, claims);
  const item = view.work[id];

  if (!item) {
    throw new ClaimError('not-found', `claimWork: work "${id}" not found.`);
  }

  const priorVisits = visitCount(rawEvents, id);
  const branch = branchNameFor(id);
  const branchAlreadyExists = branchExists(repoRoot, branch);

  const rootId = resolveRoot(view, id);
  const isLeaf = rootId !== id;
  const rootBranch = isLeaf ? branchNameFor(rootId) : undefined;
  const rootBranchExists = isLeaf && branchExists(repoRoot, rootBranch);
  const baseRef = rootBranchExists ? rootBranch : undefined;

  if (isolate && isLeaf) {
    const unmergedDeps = (item.deps ?? []).filter((dep) => !isResolvedStatus(view.work[dep]));
    if (unmergedDeps.length > 0) {
      throw new ClaimError(
        'deps-not-merged',
        `claimWork: leaf "${id}" has dep(s) not yet status:done — ${unmergedDeps.join(', ')} — forking from "${rootBranch}" now risks missing their content; approve/merge them into "${rootBranch}" first.`,
      );
    }
  }

  const activeClaim = claims[id];
  const effectiveClaimRole = item.claimRole || activeClaim?.claimRole;

  const isPotentialStaleClaimReclaim = isolate
    && (activeClaim || item.status === 'doing')
    && (effectiveClaimRole === 'human' || effectiveClaimRole === 'session')
    && (actor === 'session' || actor === 'human')
    && isReclaimEligible(repoRoot, id, effectiveClaimRole);

  const ceiling = readSharedConfigOrEmpty(path.dirname(dir))?.workerSlots?.ceiling;

  // tsk-40m (docs/architect/doing-coordination-redesign.md): claim time no
  // longer writes a durable work.move(->doing), so the ORIGINAL claim's
  // branchHeadAtTake no longer lands on the item's own sticky top-level
  // field (that field is only ever set by a work.move payload) — it now
  // lives on the settle's own work.attempt, folded into item.lastAttempt.
  const priorBranchHeadAtTake = item.lastAttempt?.branchHeadAtTake;
  const isClaimLockReclaim = branchAlreadyExists
    && typeof priorBranchHeadAtTake === 'string'
    && priorBranchHeadAtTake
    && latestTodoReleaseTrigger(rawEvents, id) === 'claim-lock-3b';

  let branchHeadAtTake;
  if (isClaimLockReclaim) {
    branchHeadAtTake = priorBranchHeadAtTake;
  } else if (branchAlreadyExists) {
    branchHeadAtTake = resolveRefSha(repoRoot, branch);
  } else if (rootBranchExists) {
    branchHeadAtTake = resolveRefSha(repoRoot, rootBranch);
  } else {
    branchHeadAtTake = head;
  }

  const isBranchTake = item.status === 'blocked' && branchAlreadyExists;
  const expectedStatus = isBranchTake ? 'blocked' : 'todo';
  const useBranchSource = isolate || isBranchTake;

  if (
    isolate
    && !isBranchTake
    && (activeClaim || item.status === 'doing')
    && (effectiveClaimRole === 'human' || effectiveClaimRole === 'session')
    && (actor === 'session' || actor === 'human')
    && isReclaimEligible(repoRoot, id, effectiveClaimRole)
  ) {
    try {
      let adminRelease = null;
      if (activeClaim) {
        // tsk-40m code-review finding (high, D4/D8): releasing a claim
        // used to just delete the runtime claim file, with no durable
        // trace — a reclaimed item read identical to one that never
        // started. Record the attempt first so attemptCount/lastAttempt
        // (replay.mjs) can tell "started then reclaimed" apart from
        // "never started". `phase` mirrors anti-loop.mjs's own
        // executing-stage check (claim-lock) so a reclaim of a clarify/
        // decompose-phase claim never inflates the execute-phase budget.
        const claimDomain = getDomain(item.domain);
        const claimPhase = effectiveStep(item, claimDomain) === stepForPhase(claimDomain, 'execute', item.kind)
          ? 'execute'
          : (item.workflowStep || 'unknown');
        recordClaimAttempt(dir, { id, phase: claimPhase, result: 'reclaimed', claimId: activeClaim.claimId, actor: activeClaim.actor });
        // Another session's claim, past its liveness threshold: released
        // through the named admin path, never the owner-only default.
        const rel = releaseClaim(dir, { id, claimId: activeClaim.claimId, adminReason: 'stale-claim-reclaim' });
        if (rel.admin) adminRelease = { ...rel.admin, claimId: activeClaim.claimId };
      } else if (item.status === 'doing') {
        moveWork(dir, { id, to: 'todo', expectedStatus: 'doing' });
      }
      const activityAt = lastActivityAt(repoRoot, id);
      addDecision(dir, {
        id,
        text: `stale-claim-reclaim: released ${effectiveClaimRole} claim (last activity ${activityAt === null ? 'unknown' : new Date(activityAt).toISOString()})`,
        source: 'claimWork',
        kind: 'engine',
        rationale: `docs/history/session-claim-liveness/CONTEXT.md D2/D4/D5 — worktree activity signal past the ${effectiveClaimRole === 'runner' ? 'agentMs' : 'humanMs'} threshold, reclaimed by a live ${actor} claim attempt`,
        // Another writer's claim was released: keep who owned it and who released it.
        ...(adminRelease ? { admin: adminRelease } : {}),
      });
    } catch (err) {
      if (!(err instanceof FsmError) || err.category !== 'conflict') throw err;
    }
  }

  // tsk-40m code-review finding (blocker, TOCTOU): everything above took real
  // wall-clock time with no lock held, long enough for a genuinely DIFFERENT
  // process to durably move this item or take the last worker slot. So the
  // fresh read, the status check, the worker-slot ceiling check and the
  // claim write are one `state` transaction: no other durable write or claim
  // can land between the read and the claim file being written.
  const runtimeClaim = withMainState(dir, (tx) => {
    const freshDurableView = foldEvents(readRawEvents(dir));
    const freshStatus = freshDurableView.work[id]?.status;
    if (freshStatus !== expectedStatus) {
      throw new ClaimError(
        'conflict',
        `claimWork: expected "${id}" durable status "${expectedStatus}" but found "${freshStatus}" (durable state changed since read)`,
      );
    }
    const freshRevision = getItemDurableRevision(freshDurableView, id);

    if (!isPotentialStaleClaimReclaim) {
      const room = hasWorkerSlotRoom(buildEffectiveView(freshDurableView, readClaims(dir)), { ceiling, excludeId: id });
      if (!room.allowed) {
        throw new ClaimError(
          'worker-slot-ceiling',
          `claimWork: worker-slot ceiling reached — ${room.occupied} of ${room.ceiling} slots in use; finish or park a running item before claiming "${id}".`,
          { occupied: room.occupied, ceiling: room.ceiling },
        );
      }
    }

    return acquireClaimTx(tx, {
      id,
      actor,
      source: useBranchSource ? 'branch' : 'main',
      branch: useBranchSource ? branch : undefined,
      branchHeadAtTake: useBranchSource ? branchHeadAtTake : undefined,
      headAtTake: useBranchSource ? undefined : head,
      claimTrigger,
      preClaimStatus: freshStatus,
      preClaimRevision: freshRevision,
      claimRole: actor,
    });
  });

  if (!skipOutcome) {
    addOutcome(dir, {
      id,
      predicted: {
        size: item.size ?? DEFAULTS.size,
        deps: item.deps?.length ?? 0,
        priorVisits,
        role: actor,
        branchHeadAtTake: useBranchSource ? branchHeadAtTake : undefined,
        headAtTake: useBranchSource ? undefined : head,
      },
    });
  }

  const claim = {
    id,
    claimId: runtimeClaim.claimId,
    from: expectedStatus,
    to: 'doing',
    role: actor,
    seq: runtimeClaim.claimId,
    source: useBranchSource ? 'branch' : 'main',
    branch: useBranchSource ? branch : undefined,
    branchHeadAtTake: useBranchSource ? branchHeadAtTake : undefined,
    headAtTake: useBranchSource ? undefined : head,
  };

  if (!isolate) return claim;
  let worktree;
  try {
    // A fresh branch forks from the same commit the claim recorded; the
    // worktree-admin mutex (rank 40) is taken here, with no other lock held.
    worktree = createClaimWorktree(repoRoot, id, { worktreeDir, baseRef, startSha: head, scope });
  } catch (err) {
    releaseClaim(dir, { id, claimId: runtimeClaim.claimId });
    throw err;
  }
  return { ...claim, worktree };
}

// dispatch/assignment-policy.mjs — Dispatch policy resolution for assignments (Step 01 Slice 3a / Step 03).
//
// Resolution order:
// Global defaults -> Domain defaults -> Workflow defaults -> Stage defaults
// -> Operation / taskSpec defaults -> Role defaults -> Persona defaults
// -> Work-item policy -> Assignment explicit policy -> Human / CLI explicit override
// -> Governance gate
//
// Invariants:
// - Constraints accumulate and fail closed.
// - Tier resolves to the strongest required tier (cannot be weakened).
// - Literal model names are accepted only from Assignment or human/CLI override (never workflow YAML).
// - Executor/provider preference uses the most specific value.
//
// Step 08 R3 (declared CoordinationProtocol materialization): an optional
// `cliOverride.policyProvenance` object (`{tier?, persona?, executor?,
// visibility?}`, each a `{scope, id?}` pair) lets a caller that already
// composed a full scoped policy stack upstream (runner/definition/operation/
// role/actor/assignment/cli -- coordination/session-engine.mjs's
// `dispatchDeclaredOperation`) record which scope actually won, instead of
// this resolver's own generic `{scope: 'cliOverride'}` label. Existing callers
// omit `policyProvenance`, so the field is purely additive.

import { MODEL_POLICY_TIERS, RunnerConfigError, REASONING_EFFORT_VALUES, DEFAULT_RIGOR_TO_TIER, assertReasoningEffort } from './config.mjs';
import { resolveTierModel, deriveProviderFamily, tierCellMissingDetail } from './resolve.mjs';
import { REPEAT_MODE_VALUES } from './execution-contract.mjs';
import { checkProviderDisallowed } from './provider-adapter.mjs';
import { RIGOR_VALUES, RIGOR_RANK, resolveStrongerRigor } from '../rigor.mjs';
import { deriveOperationCapability } from '../operation-capability.mjs';
export const TIER_STRENGTH = Object.freeze({
  nano: 1,
  mini: 2,
  standard: 3,
  advanced: 4,
  flagship: 5,
  frontier: 6,
});


export { RIGOR_VALUES, RIGOR_RANK };

// Option names that once carried a Work item (or the pieces dispatch used to read off one)
// into dispatch. Dispatch takes generic inputs only, so a caller still passing one is refused
// instead of having it silently ignored.
export const WORK_ITEM_KEYS = Object.freeze(['work', 'workItem']);
const WORK_ITEM_INPUT_KEYS = Object.freeze([...WORK_ITEM_KEYS, 'workExecutorId']);

/**
 * Throws when `params` still carries a Work item input; `where` names the entry point. `keys`
 * narrows the check (a `--work` hint legitimately carries `workExecutorId`).
 */
export function refuseWorkItemInput(params, where, keys = WORK_ITEM_INPUT_KEYS) {
  const found = params && typeof params === 'object' ? keys.filter((key) => Object.hasOwn(params, key)) : [];
  if (found.length) {
    throw new RunnerConfigError(
      `${where} takes no Work item (${found.join(', ')}): pass its demand as generic inputs (assignment rigor/domain, a work hint, capability hints, agent type)`,
    );
  }
}

// Phase 03 (executor-policy-dispatch-seams) — canonical reasoningEffort.
// Most-specific-wins (design.md §4 field rules table).
// executor-profile-schema-migration) so `validateExecutorEntryShape`'s new
// `supports.reasoningEffort` check can reuse the exact same vocabulary
// without a config.mjs -> assignment-policy.mjs -> config.mjs import cycle;
// re-exported here unchanged so every existing caller of this module keeps
// working byte-identically.
export { REASONING_EFFORT_VALUES };
/**
 * The reasoningEffort a resolved policy asks the provider CLI to run at, or
 * undefined when nobody asked: an explicit level (a `--effort` override or an
 * operation policy) is rendered into the launch; one merely derived from rigor
 * is not, because no dispatch has ever been launched with it and turning it on
 * would change every run's cost at once.
 */
export function explicitReasoningEffort(policy) {
  const scope = policy?.provenance?.reasoningEffort?.source?.scope;
  return scope && scope !== 'derived' ? policy.reasoningEffort : undefined;
}

export const REASONING_EFFORT_DEFAULT_FROM_RIGOR = Object.freeze({
  low: 'low',
  standard: 'medium',
  high: 'high',
  critical: 'max',
});

// Phase 03's compatibility alias seam (design.md §5.1) is retired
// (executor-id-consolidation Step 2): every id it keyed off
// (claude-reviewer/claude-reviewer-herdr/codex-readonly) no longer exists
// as a registered executor at all, so `primaryExecutor` can never equal
// one -- the seam had already become permanently unreachable dead code
// (step 3 below's own registration throw fires first, always). The same
// personas/reasoningEffort/visibility it used to compatibility-patch are
// now expressed directly via `actors[].invocation` (a specific
// `claude`/`codex` invocation already carries `--effort high`/confinement
// in its own declared args) or capabilities.<name>.prefer's invocation pin
// -- no resolver-side patching needed any more.

/**
 * Return the stronger of two tiers based on rigor hierarchy.
 *
 * @param {string} tierA
 * @param {string} tierB
 * @returns {string}
 */
export function resolveStrongerTier(tierA, tierB) {
  for (const value of [tierA, tierB]) {
    if (value !== undefined && value !== null && !MODEL_POLICY_TIERS.includes(value)) {
      throw new RunnerConfigError(`invalid tier "${value}". Valid tiers: [${MODEL_POLICY_TIERS.join(', ')}]`);
    }
  }
  if (tierA === undefined || tierA === null) return tierB ?? 'standard';
  if (tierB === undefined || tierB === null) return tierA;
  return TIER_STRENGTH[tierB] > TIER_STRENGTH[tierA] ? tierB : tierA;
}

/**
 * Resolve `primaryExecutor` to its REGISTERED config entry (Phase 00 R6,
 * fixes H2a/H2b) and derive its provider family (Phase 00 R6 fix F1) --
 * extracted verbatim from `resolveAssignmentDispatchPolicy`'s own former
 * inline steps 3b/4 (dispatch-engine-liveness-hardening Phase 7, C3
 * finding) so `cli.mjs`'s `executeExecutorCli` can derive the SAME
 * `resolvedProvider` it needs for governance without running this
 * resolver's entire tier/quality/persona/model computation. Same checks,
 * same order, same throws as before this extraction -- a pure move.
 *
 * @param {object} params
 * @param {object} [params.runnerConfig]
 * @param {string} params.primaryExecutor
 * @param {string} [params.explicitProviderModel] an already-resolved
 *   providerModel override (cliOverride/opPolicy), when the caller has one
 * @param {{disallowedProviders?: string[], disallowedExecutors?: string[]}} [params.options]
 * @returns {{resolvedProvider: string, registeredExecutorEntry: object|undefined}}
 */
export function resolveExecutorProvider({ runnerConfig, primaryExecutor, options = {} }) {
  const hasExecutorRegistry = Boolean(runnerConfig && runnerConfig.executors && typeof runnerConfig.executors === 'object');
  const hasGovernanceOptions =
    (Array.isArray(options.disallowedProviders) && options.disallowedProviders.length > 0) ||
    (Array.isArray(options.disallowedExecutors) && options.disallowedExecutors.length > 0);
  if (hasGovernanceOptions && !hasExecutorRegistry) {
    throw new RunnerConfigError(
      `governance requires "disallowedProviders"/"disallowedExecutors" but runnerConfig.executors is absent -- provider family cannot be verified for executor "${primaryExecutor}"`,
    );
  }
  const registeredExecutorEntry = hasExecutorRegistry ? runnerConfig.executors[primaryExecutor] : undefined;
  const isImplicitDefaultExecutor = primaryExecutor === 'claude' || primaryExecutor === runnerConfig?.executor?.command || primaryExecutor === runnerConfig?.executor?.invocations?.[0]?.command || primaryExecutor === runnerConfig?.executor?.invocations?.[0]?.id;
  if (hasExecutorRegistry && !registeredExecutorEntry && !isImplicitDefaultExecutor) {
    throw new RunnerConfigError(`preferExecutor "${primaryExecutor}" is not a registered executor (runnerConfig.executors has no such entry).`);
  }
  const registeredExecutorCommand = registeredExecutorEntry?.invocations?.find((inv) => inv.via === 'cli')?.command;
  const resolvedProvider = registeredExecutorEntry
    ? deriveProviderFamily(registeredExecutorEntry, registeredExecutorCommand)
    : isImplicitDefaultExecutor
      ? deriveProviderFamily({ command: runnerConfig?.executor?.command }, primaryExecutor)
      : primaryExecutor;
  return { resolvedProvider, registeredExecutorEntry };
}

/**
 * Governance gate (Phase 00 R6/F2): reject an already-resolved provider
 * family / executor id pair against `options.disallowedProviders`/
 * `.disallowedExecutors`. Extracted from `resolveAssignmentDispatchPolicy`
 * (dispatch-engine-liveness-hardening Phase 7, C3 finding) so a caller that
 * has already resolved its own provider/executor (e.g. `cli.mjs`'s
 * `executeExecutorCli`/`spawnWorker`, which used to run this resolver's
 * entire tier/quality/persona/model computation only to reach this same
 * check) can run the SAME governance check directly, without a second,
 * redundant resolver call whose rich result it then discarded.
 *
 * @param {object} params
 * @param {string} params.primaryExecutor the resolved executor id
 * @param {string} params.providerModel the resolved provider family
 * @param {{disallowedProviders?: string[], disallowedExecutors?: string[]}} [params.options]
 * @returns {{canonicalProvider: string}}
 */
export function resolveExecutorGovernance({ primaryExecutor, providerModel, options = {} }) {
  const providerGov = checkProviderDisallowed(options.disallowedProviders, providerModel);
  if (providerGov.disallowed) {
    throw new RunnerConfigError(`governance gate rejected provider "${providerGov.canonicalProvider}": disallowed egress`, {
      code: 'governance.disallowed-provider',
    });
  }
  if (options.disallowedExecutors && options.disallowedExecutors.includes(primaryExecutor)) {
    throw new RunnerConfigError(`governance gate rejected executor "${primaryExecutor}": disallowed`, {
      code: 'governance.disallowed-executor',
    });
  }
  return { canonicalProvider: providerGov.canonicalProvider };
}

/**
 * Resolve effective dispatch policy for an Assignment before execution attempt (Step 03 §3.1).
 *
 * @param {object} params
 * @param {object} params.assignment Assignment object (required). Its own `rigor` and
 *   `domain` are the caller's demand: the Work layer folds an item's rigor and risk into
 *   `rigor` before dispatch sees it, so dispatch never reads a Work item.
 * @param {object} [params.runnerConfig] Runner configuration (optional)
 * @param {object} [params.cliOverride] Human / CLI overrides (optional)
 * @param {object} [params.options] Governance and lookup options
 * @returns {Readonly<object>} Effective dispatch policy
 */
// M12: `cliOverride` renamed to `policyInputs` -- the merged PolicyPatch a
// caller wants layered on top of the assignment/work/operation stack was
// never CLI-specific (session-engine.mjs's own coordination dispatch path
// builds and passes one with no CLI in sight), so the old name described
// where the FIRST caller of this function happened to source it from, not
// what the parameter actually is. `cliOverride` is kept as a working alias
// for one release rather than a breaking rename -- accepted alongside
// `policyInputs`, with `policyInputs` winning when a caller (unusually)
// supplies both.
export function resolveAssignmentDispatchPolicy({
  assignment,
  runnerConfig,
  cliOverride = {},
  policyInputs,
  options = {},
}) {
  // `policyInputs` wins when a caller supplies both; every reference below
  // stays named `cliOverride` (including provenance's own `{scope:
  // 'cliOverride'}` stamp -- an internal attribution label, not part of
  // this rename) since reassigning the one binding here covers all of them
  // without a large, error-prone rename sweep across this whole function.
  if (policyInputs !== undefined) cliOverride = policyInputs;
  refuseWorkItemInput(arguments[0], 'resolveAssignmentDispatchPolicy()');
  if (!assignment || typeof assignment !== 'object') {
    throw new RunnerConfigError('resolveAssignmentDispatchPolicy requires an assignment object');
  }

  const opPolicy = assignment.policy === undefined ? {} : assignment.policy;
  if (!opPolicy || typeof opPolicy !== 'object' || Array.isArray(opPolicy)) {
    throw new RunnerConfigError('assignment.policy must be an object when provided');
  }
  const retiredMinTier = ['min', 'Tier'].join('');
  if (Object.prototype.hasOwnProperty.call(opPolicy, retiredMinTier)) {
    throw new RunnerConfigError(`assignment policy field "${retiredMinTier}" was removed; normalize persisted assignments at the load boundary or use "rigor"/"tier"`);
  }
  if (opPolicy._fromYaml && opPolicy.tier !== undefined) {
    throw new RunnerConfigError('workflow YAML cannot set explicit tier; use rigor, or set tier at actor/assignment/CLI scope');
  }

  // Reject literal model in operation policy if it was not explicitly stamped as assignment-level
  if (opPolicy.model && !assignment._allowLiteralModel && !cliOverride.model) {
    // If model comes from declared operation YAML, it is prohibited
    if (opPolicy._fromYaml) {
      throw new RunnerConfigError('workflow YAML cannot pin literal model names; use rigor or persona');
    }
  }

  const opId = assignment.operation;
  const strength = (t) => TIER_STRENGTH[t] ?? 0;
  const rigorToTier = runnerConfig?.rigorToTier ?? runnerConfig?.runner?.rigorToTier ?? DEFAULT_RIGOR_TO_TIER;
  const rigorStrength = (r) => RIGOR_RANK[r] ?? 0;

  // 1. Rigor Resolution (demand side, monotonic: highest explicit
  // requirement wins; the implicit standard is only a final fallback).
  if (opPolicy.rigor !== undefined && !RIGOR_VALUES.includes(opPolicy.rigor)) {
    throw new RunnerConfigError(`invalid operation rigor "${opPolicy.rigor}". Valid rigors: [${RIGOR_VALUES.join(', ')}]`);
  }
  let effectiveRigor = opPolicy.rigor ?? 'standard';
  let rigorSource = opPolicy.rigor !== undefined ? { scope: 'opPolicy', id: opId } : { scope: 'default' };
  // The implicit standard is a fallback, not a floor. The first explicit
  // source may therefore select low; only later explicit sources are
  // monotonic raise-only.
  // The caller's own rigor demand (a Work item's rigor or risk, folded by the Work layer).
  // First explicit source may select it outright; after an operation rigor it only raises.
  if (assignment.rigor !== undefined) {
    if (!RIGOR_VALUES.includes(assignment.rigor)) {
      throw new RunnerConfigError(`invalid assignment rigor "${assignment.rigor}". Valid rigors: [${RIGOR_VALUES.join(', ')}]`);
    }
    if (rigorSource.scope === 'default' || rigorStrength(assignment.rigor) > rigorStrength(effectiveRigor)) {
      effectiveRigor = rigorSource.scope === 'default' ? assignment.rigor : resolveStrongerRigor(effectiveRigor, assignment.rigor);
      rigorSource = { scope: 'assignment', id: assignment.assignmentId ?? assignment.workId ?? null };
    }
  }

  // Capability floor (D19). Declared capability wins. For assignments built
  // from operations without policy.capability, reuse the canonical derivation
  // shared with coordination binding; never import the verb layer here.
  const derivedCapability = deriveOperationCapability(
    { id: assignment.operation, policy: opPolicy, result: assignment.result ?? { kind: assignment.resultKind } },
    { domain: assignment.domain, primaryCapability: assignment.primaryCapability },
    runnerConfig,
  );
  const targetCap = opPolicy.capability ?? assignment.capability ?? derivedCapability.name;
  if (targetCap && runnerConfig?.capabilities?.[targetCap]?.rigor !== undefined) {
    const capRigor = runnerConfig.capabilities[targetCap].rigor;
    if (!RIGOR_VALUES.includes(capRigor)) {
      throw new RunnerConfigError(`invalid capability rigor "${capRigor}" for "${targetCap}". Valid rigors: [${RIGOR_VALUES.join(', ')}]`);
    }
    if (rigorSource.scope === 'default' || rigorStrength(capRigor) > rigorStrength(effectiveRigor)) {
      effectiveRigor = rigorSource.scope === 'default' ? capRigor : resolveStrongerRigor(effectiveRigor, capRigor);
      rigorSource = { scope: 'capability', id: targetCap };
    }
  }

  // Caller/CLI rigor.
  const cliRigor = cliOverride.rigor;
  if (cliRigor !== undefined) {
    if (!RIGOR_VALUES.includes(cliRigor)) {
      throw new RunnerConfigError(`invalid override rigor "${cliRigor}". Valid rigors: [${RIGOR_VALUES.join(', ')}]`);
    }
    if (rigorSource.scope === 'default' || rigorStrength(cliRigor) > rigorStrength(effectiveRigor)) {
      effectiveRigor = rigorSource.scope === 'default' ? cliRigor : resolveStrongerRigor(effectiveRigor, cliRigor);
      rigorSource = cliOverride.policyProvenance?.rigor ?? { scope: 'cliOverride' };
    }
  }

  if (!RIGOR_VALUES.includes(effectiveRigor)) {
    throw new RunnerConfigError(`unrecognized rigor "${effectiveRigor}". Valid rigors: [${RIGOR_VALUES.join(', ')}]`);
  }

  // 1b. Map rigor -> tier via rigorToTier. Validate before considering any
  // explicit tier, otherwise a valid override could mask a malformed map.
  const derivedTier = rigorToTier[effectiveRigor];
  if (!MODEL_POLICY_TIERS.includes(derivedTier)) {
    throw new RunnerConfigError(
      `rigorToTier maps rigor "${effectiveRigor}" to invalid tier "${derivedTier}". Valid tiers: [${MODEL_POLICY_TIERS.join(', ')}]`,
    );
  }
  let effectiveTier = derivedTier;
  let tierSource = { scope: 'rigor', id: effectiveRigor };

  // Explicit tiers are independent raise-only inputs. Validate every source
  // before composition so a stronger source cannot mask a malformed weaker
  // one.

  const tierOverrideProvenance = cliOverride.policyProvenance?.tier;
  if (
    cliOverride.tier !== undefined &&
    tierOverrideProvenance !== undefined &&
    !['actor', 'assignment', 'cli', 'cliOverride'].includes(tierOverrideProvenance.scope)
  ) {
    throw new RunnerConfigError(
      `explicit tier provenance scope "${tierOverrideProvenance.scope}" is not allowed; tier may be explicit only at actor, assignment, or CLI scope`,
    );
  }
  const explicitTiers = [
    { value: opPolicy.tier, source: { scope: 'opPolicy', id: opId } },
    { value: cliOverride.tier, source: cliOverride.policyProvenance?.tier ?? { scope: 'cliOverride' } },
  ];
  for (const { value, source } of explicitTiers) {
    if (value === undefined) continue;
    if (!MODEL_POLICY_TIERS.includes(value)) {
      throw new RunnerConfigError(`invalid explicit tier "${value}". Valid tiers: [${MODEL_POLICY_TIERS.join(', ')}]`);
    }
    if (strength(value) > strength(effectiveTier)) {
      effectiveTier = resolveStrongerTier(effectiveTier, value);
      tierSource = source;
    }
  }

  if (!MODEL_POLICY_TIERS.includes(effectiveTier)) {
    throw new RunnerConfigError(`unrecognized tier "${effectiveTier}". Valid tiers: [${MODEL_POLICY_TIERS.join(', ')}]`);
  }

  // 1c. Executor preference
  const primaryExecutor =
    cliOverride.preferExecutor ??
    opPolicy.preferExecutor ??
    runnerConfig?.executor?.command ??
    (runnerConfig?.executor?.invocations?.[0]?.command ?? runnerConfig?.executor?.invocations?.[0]?.id) ??
    'claude';
  const executorSource = cliOverride.preferExecutor
    ? (cliOverride.policyProvenance?.executor ?? { scope: 'cliOverride' })
    : opPolicy.preferExecutor
      ? { scope: 'opPolicy', id: opId }
      : { scope: 'default' };


  // Phase 03: canonical reasoningEffort, most-specific-wins.
  // Precedence mirrors every other field in this resolver:
  // explicit cliOverride/opPolicy > derived from canonical rigor.
  const explicitReasoningEffort = cliOverride.reasoningEffort ?? opPolicy.reasoningEffort;
  let reasoningEffort;
  let reasoningEffortSource;
  if (explicitReasoningEffort !== undefined) {
    reasoningEffort = assertReasoningEffort(explicitReasoningEffort);
    reasoningEffortSource = cliOverride.reasoningEffort ? { scope: 'cliOverride' } : { scope: 'opPolicy', id: opId };
  } else {
    reasoningEffort = REASONING_EFFORT_DEFAULT_FROM_RIGOR[effectiveRigor] ?? 'medium';
    reasoningEffortSource = { scope: 'derived', id: `rigor.${effectiveRigor}` };
  }

  // 2. Persona Resolution
  const resolvedPersona =
    cliOverride.preferPersona ??
    opPolicy.preferPersona ??
    (assignment.role === 'reviewer' ? 'code-reviewer' : undefined);
  const personaSource = cliOverride.preferPersona
    ? (cliOverride.policyProvenance?.persona ?? { scope: 'cliOverride' })
    : opPolicy.preferPersona
      ? { scope: 'opPolicy', id: opId }
      : resolvedPersona
          ? { scope: 'default', id: assignment.role }
          // Phase 00 R7/F4: still `{ scope: 'default' }` (no id) rather than
          // `undefined` when no persona resolves at all -- provenance.persona.source
          // must always be an object, per the documented shape.
          : { scope: 'default' };

  // 3. Executor Preference Resolution (registry/governance)
  const declaredFallbacks = cliOverride.fallbackExecutors ?? opPolicy.fallbackExecutors ?? [];
  // `fallbackExecutors` is reserved-not-executed (Phase 00 R10): only
  // `executorList[0]` (primaryExecutor) is ever actually dispatched --
  // entries beyond it are recorded for future automatic-failover, never
  // validated for registration and never spawned by this resolver.
  const executorList = [
    primaryExecutor,
    ...declaredFallbacks.filter((e) => e !== primaryExecutor),
  ];

  // 3b/4 (registry validation, provider derivation): extracted to
  // `resolveExecutorProvider` (dispatch-engine-liveness-hardening Phase 7,
  // C3) -- see that function's own doc comment for why, and
  // `docs/history/executor-policy-dispatch-seams/` (H2a/H2b/RT1/F1) for the
  // edge cases its logic still encodes unchanged (pure move, same checks,
  // same order, same throws). The governance THROWS (disallowedProviders/
  // disallowedExecutors, step 7 below) stay in their original position,
  // AFTER quality/persona/visibility/repeatMode/constraints resolution --
  // error (invalid rigor/repeatMode) that used to throw first for
  // the same malformed input, a real ordering change this extraction must
  // not introduce.
  const { resolvedProvider, registeredExecutorEntry } = resolveExecutorProvider({
    runnerConfig,
    primaryExecutor,
    options,
  });
  const providerSource = registeredExecutorEntry
    ? { scope: 'registeredExecutor', id: primaryExecutor }
    : executorSource;
  let resolvedModel = null;
  // Phase 00 R7/F4: defaults to `{ scope: 'default' }` below when no
  // override/runnerConfig resolves a source -- provenance.model.source must
  // always be an object, never `undefined`, per the documented shape.
  let modelSource = { scope: 'default' };

  if (cliOverride.model) {
    resolvedModel = cliOverride.model;
    modelSource = { scope: 'cliOverride' };
  } else if (opPolicy.model) {
    resolvedModel = opPolicy.model;
    modelSource = { scope: 'opPolicy', id: opId };
  } else if (runnerConfig) {
    // Direct tier resolution fails closed when the provider/tier pair is
    // unsupported. The previous fallback repeated the identical lookup and
    // could never recover from a missing mapping.
    try {
      resolvedModel = resolveTierModel(runnerConfig, effectiveTier, resolvedProvider);
    } catch (err) {
      throw new RunnerConfigError(`tier-cell-missing: ${tierCellMissingDetail(resolvedProvider, effectiveTier)}`, { code: 'tier-cell-missing' });
    }
    modelSource = { scope: 'placement-policy', id: `${resolvedProvider}.${effectiveTier}` };
  }

  // 5. Visibility Resolution
  const resolvedVisibility = cliOverride.visibility ?? opPolicy.visibility ?? 'headless';
  const visibilitySource = cliOverride.visibility
    ? (cliOverride.policyProvenance?.visibility ?? { scope: 'cliOverride' })
    : opPolicy.visibility
      ? { scope: 'opPolicy', id: opId }
      : { scope: 'default' };

  // 5b. RepeatMode Resolution (Step 09/P03 fallback-and-effect-boundary
  // contract): declared explicitly on the operation/protocol YAML
  // (`opPolicy.repeatMode`) or a caller's own `cliOverride.repeatMode` --
  // NEVER derived from `assignment.mutation`, which this resolver does not
  // read anywhere in this function. `mutation` and `repeatMode` are
  // independent axes (mutation: does this dispatch write state; repeatMode:
  // may ITS OWN declared operation be repeated once an effect has already
  // reached an external sink) and must stay that way -- undeclared on both
  // sides simply resolves to `null`, which `dispatch/recovery.mjs`'s
  // `assess` treats as a config error, never as an inferred value.
  const resolvedRepeatMode = cliOverride.repeatMode ?? opPolicy.repeatMode;
  if (resolvedRepeatMode !== undefined && !REPEAT_MODE_VALUES.includes(resolvedRepeatMode)) {
    throw new RunnerConfigError(`invalid repeatMode "${resolvedRepeatMode}". Valid repeatModes: [${REPEAT_MODE_VALUES.join(', ')}]`);
  }
  const repeatModeSource = cliOverride.repeatMode
    ? { scope: 'cliOverride' }
    : opPolicy.repeatMode
      ? { scope: 'opPolicy', id: opId }
      : { scope: 'default' };

  // 6. Constraints Accumulation
  const skills = Array.isArray(assignment.skills) ? assignment.skills : [];
  const constraints = {
    requiresSkills: Object.freeze([...skills]),
    ...(opPolicy.constraints || {}),
  };
  const constraintsSource = { scope: 'assignment', id: assignment.assignmentId };

  // 7. Governance check (Phase 00 R6/F2: `resolvedProvider` and
  // `primaryExecutor` are checked as two DISTINCT fields, never merged into
  // one -- `disallowedProviders` names a provider family, never a raw
  // executor id, per its own option name; `disallowedExecutors` is its
  // executor-id-keyed counterpart, for governance configs that need to
  // block one specific registered executor entry even when its declared
  // provider family is otherwise trusted). Extracted to `resolveExecutorGovernance`
  // (dispatch-engine-liveness-hardening Phase 7, C3) so `executeExecutorCli`/
  // `spawnWorker` (cli.mjs) can run the SAME governance check directly
  // against their own already-resolved provider/executor without paying for
  // this resolver's full tier/quality/persona/model computation just to
  // reach these two throws.
  const { canonicalProvider } = resolveExecutorGovernance({ primaryExecutor, providerModel: resolvedProvider, options });
  const governanceSource = { scope: 'governance', id: canonicalProvider };

  const effectivePolicy = {
    role: assignment.role,
    persona: resolvedPersona,
    executorPreference: Object.freeze(executorList),
    executorId: primaryExecutor,
    providerModel: resolvedProvider,
    rigor: effectiveRigor,
    tier: effectiveTier,
    model: resolvedModel,
    reasoningEffort,
    visibility: resolvedVisibility,
    repeatMode: resolvedRepeatMode ?? null,
    constraints: Object.freeze(constraints),
    provenance: Object.freeze({
      executor: Object.freeze({ value: primaryExecutor, source: Object.freeze(executorSource) }),
      provider: Object.freeze({ value: resolvedProvider, source: Object.freeze(providerSource) }),
      model: Object.freeze({ value: resolvedModel, source: modelSource ? Object.freeze(modelSource) : undefined }),
      rigor: Object.freeze({ value: effectiveRigor, source: Object.freeze(rigorSource) }),
      tier: Object.freeze({ value: effectiveTier, source: Object.freeze(tierSource) }),
      reasoningEffort: Object.freeze({ value: reasoningEffort, source: Object.freeze(reasoningEffortSource) }),
      persona: Object.freeze({ value: resolvedPersona, source: personaSource ? Object.freeze(personaSource) : undefined }),
      visibility: Object.freeze({ value: resolvedVisibility, source: Object.freeze(visibilitySource) }),
      repeatMode: Object.freeze({ value: resolvedRepeatMode ?? null, source: Object.freeze(repeatModeSource) }),
      constraints: Object.freeze({ value: constraints, source: Object.freeze(constraintsSource) }),
      governance: Object.freeze({ value: 'allowed', source: Object.freeze(governanceSource) }),
    }),
  };
  return Object.freeze(effectivePolicy);
}

